export enum Category {
  INCIDENT = "INCIDENT",
  BUG = "BUG",
  ACCESS = "ACCESS",
  SUPPORT = "SUPPORT",
  OTHER = "OTHER",
}

export enum Priority {
  LOW = "LOW",
  MEDIUM = "MEDIUM",
  HIGH = "HIGH",
  CRITICAL = "CRITICAL",
}

export enum Risk {
  LOW = "LOW",
  MEDIUM = "MEDIUM",
  HIGH = "HIGH",
}

export enum SuggestedTeam {
  INFRASTRUCTURE = "INFRASTRUCTURE",
  DEVELOPMENT = "DEVELOPMENT",
  SUPPORT = "SUPPORT",
  HUMAN_REVIEW = "HUMAN_REVIEW",
}

export interface TicketInput {
  title: string;
  description: string;
}

// Três degraus, não um float: uma heurística não tem precisão de 0.83.
export type Confidence = 0.5 | 0.7 | 0.9;

// O que qualquer classificador devolve.
export interface ClassifierResult {
  category: Category;
  priority: Priority;
  risk: Risk;
  suggestedTeam: SuggestedTeam;
  confidence: Confidence;
  summary: string;
  rationale: string;
}

import type { ClassifierResult, TicketInput } from "./triage.ts";

export interface TriageClassifier {
  classify(input: TicketInput): Promise<ClassifierResult>;
}

// Três falhas com consequências diferentes para quem chama.
export class ClassifierTimeoutError extends Error {
  override readonly name = "ClassifierTimeoutError";
  constructor() {
    super("Classifier request timed out");
  }
}

export class ClassifierUnavailableError extends Error {
  override readonly name = "ClassifierUnavailableError";
  constructor() {
    super("Classifier service is unavailable");
  }
}

export class ClassifierInvalidResponseError extends Error {
  override readonly name = "ClassifierInvalidResponseError";
  constructor() {
    super("Classifier returned an invalid response");
  }
}

import { Category, Priority, Risk, type ClassifierResult } from "./triage.ts";

export type LlmResult = Omit<ClassifierResult, "suggestedTeam">;

const FIELDS = ["category", "priority", "risk", "confidence", "summary", "rationale"];

// O que o schema Zod do projeto real verifica, escrito à mão:
// objeto estrito, enums válidos, confiança discreta, textos não vazios e curtos.
export function parseLlmResult(value: unknown): LlmResult | undefined {
  if (typeof value !== "object" || value === null || Array.isArray(value)) return undefined;
  const v = value as Record<string, unknown>;
  if (Object.keys(v).some((key) => !FIELDS.includes(key))) return undefined;
  if (!isOneOf(v.category, Object.values(Category))) return undefined;
  if (!isOneOf(v.priority, Object.values(Priority))) return undefined;
  if (!isOneOf(v.risk, Object.values(Risk))) return undefined;
  if (v.confidence !== 0.5 && v.confidence !== 0.7 && v.confidence !== 0.9) return undefined;
  if (!isText(v.summary, 160) || !isText(v.rationale, 240)) return undefined;
  return {
    category: v.category,
    priority: v.priority,
    risk: v.risk,
    confidence: v.confidence,
    summary: v.summary,
    rationale: v.rationale,
  };
}

function isOneOf<T extends string>(value: unknown, options: T[]): value is T {
  return typeof value === "string" && (options as string[]).includes(value);
}

function isText(value: unknown, max: number): value is string {
  return typeof value === "string" && value.trim().length > 0 && value.length <= max;
}

import { Category, SuggestedTeam } from "./triage.ts";

// Record exige uma entrada por categoria: esquecer uma não compila.
const TEAM_BY_CATEGORY: Readonly<Record<Category, SuggestedTeam>> = {
  [Category.INCIDENT]: SuggestedTeam.INFRASTRUCTURE,
  [Category.BUG]: SuggestedTeam.DEVELOPMENT,
  [Category.ACCESS]: SuggestedTeam.SUPPORT,
  [Category.SUPPORT]: SuggestedTeam.SUPPORT,
  [Category.OTHER]: SuggestedTeam.HUMAN_REVIEW,
};

export function suggestedTeamForCategory(category: Category): SuggestedTeam {
  return TEAM_BY_CATEGORY[category];
}

