import { suggestedTeamForCategory } from "./suggested-team.ts";
import type { TriageClassifier } from "./triage-classifier.ts";
import type { TicketInput, ClassifierResult } from "./triage.ts";
import { ClassifierUnavailableError, ClassifierInvalidResponseError, ClassifierTimeoutError } from "./classifier-errors.ts";
export async function requestClassifier(url: string, input: TicketInput, fetchImpl: typeof fetch, timeoutMs: number = 1000): Promise<ClassifierResult> {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);
  try {
    let response: Response;
    try { response = await fetchImpl(url + "/api/chat", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify(input), signal: controller.signal }); } catch { throw controller.signal.aborted ? new ClassifierTimeoutError() : new ClassifierUnavailableError(); }
    if (!response.ok) throw new ClassifierUnavailableError();
    let value: unknown;
    try { const envelope = await response.json(); value = JSON.parse(envelope.message.content); } catch { throw new ClassifierInvalidResponseError(); }
    const result = parseLlmResult(value);
    if (!result) throw new ClassifierInvalidResponseError();
    return { ...result, suggestedTeam: suggestedTeamForCategory(result.category) };
  } finally { clearTimeout(timer); }
}
export class LlmTriageClassifier implements TriageClassifier {
  constructor(private readonly url: string, private readonly fetchImpl: typeof fetch, private readonly timeoutMs = 1000) {}
  classify(input: TicketInput): Promise<ClassifierResult> { return requestClassifier(this.url, input, this.fetchImpl, this.timeoutMs); }
}

