import { requestClassifier, LlmTriageClassifier } from "./remote.ts";
import { ClassifierUnavailableError, ClassifierInvalidResponseError, ClassifierTimeoutError } from "./classifier-errors.ts";
const input = { title: "site down", description: "all users" };
const valid = { category: Category.INCIDENT, priority: Priority.LOW, risk: Risk.LOW, confidence: 0.9, summary: "site", rationale: "down" };
const reply = () => new Response(JSON.stringify({ message: { content: JSON.stringify(valid) } }));
test("timeout cancela e limpa", async () => { let signal: AbortSignal | undefined; let error: unknown; try { await requestClassifier("http://local", input, async (_url, init) => { signal = init?.signal as AbortSignal; return new Promise((_resolve, reject) => signal?.addEventListener("abort", () => reject(new Error("aborted")))); }, 1); } catch (caught) { error = caught; } expect(signal?.aborted).toBe(true); expect(error).toBeInstanceOf(ClassifierTimeoutError); });

